INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310012, 13681, 'South China Morning Post', 'en', 'Zhu Rongji: reformer who led China’s economic transformation through ‘minefield or abyss’', 'https://www.scmp.com/news/china/politics/article/3363824/zhu-rongji-reformer-who-led-chinas-economic-transformation-through-minefield-or-abyss', '“Regardless of what lies ahead – be it a minefield or a deep abyss – I will forge ahead unswervingly, dedicating my entire life and energy to the country until my dying day.” Those words, spoken at the dawn of his premiership, came to define Zhu Rongji, China’s towering economic reformer who died in Beijing on Wednesday. He was 97. His remarks at a press conference in 1998 came as China was undertaking sweeping state-owned enterprise (SOE) reforms that caused widespread job losses, even as it...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/12/65c64d6f-6620-4aa8-a2e3-adc22a138016_24456625.jpg?itok=jCIBkXPp&v=1786550985', '2026-08-12T16:11:47+00:00', '2026-08-12T22:56:38.048600'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310018, 13681, 'South China Morning Post', 'en', 'John Lee leads tributes as Zhu Rongji remembered for putting steel in Hong Kong’s spine', 'https://www.scmp.com/news/hong-kong/politics/article/3363819/ill-be-first-line-buy-your-bonds-how-zhu-rongji-put-steel-hong-kongs-spine', 'Hong Kong’s leader has expressed his profound sorrow over the death of former Chinese premier Zhu Rongji, paying tribute to him for supporting the city in challenging times including the 1997 Asian financial crisis. In a statement late on Wednesday night, Chief Executive John Lee Ka-chiu said he was sincerely grateful for Zhu’s care and support for Hong Kong’s economic and social development over the years, while noting his commitment to the “one country, two systems” governing principle. Zhu...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/12/63d0d5b6-5e44-4440-a107-3e13d01b291e_c9f258df.jpg?itok=MDZ9YNEI&v=1786543807', '2026-08-12T14:10:52+00:00', '2026-08-12T22:56:38.145671'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310041, 13681, 'South China Morning Post', 'en', 'Zhu Rongji, China’s chief engineer of economic reform and former premier, dies aged 97', 'https://www.scmp.com/news/china/politics/article/3363792/chinese-economic-reformer-zhu-rongji-dies-aged-97', 'Former Chinese premier Zhu Rongji, who helped engineer one of the greatest economic reforms in human history, died of an illness on Wednesday in Beijing. He was 97. Zhu, who served as China’s premier from 1998 to 2003, is remembered for shaking up the centrally planned economy, overhauling the state-owned enterprise (SOE) sector and tackling corruption. He was the mastermind behind negotiations for China’s World Trade Organization (WTO) entry in 2001, which opened China up to the international...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/12/96109313-3367-4ed1-9b3a-18186e74a256_efa87ec0.jpg?itok=U_tnKszN&v=1786530189', '2026-08-12T10:01:47+00:00', '2026-08-12T22:56:38.493556'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
