INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322341, 13681, 'The New York Times', 'en', 'In a Chinese Leader’s Death, Mourning for a More Hopeful Time', 'https://www.nytimes.com/2026/08/13/business/zhu-rongji-death-mourning-china.html', 'Tributes for former Premier Zhu Rongji reflect nostalgia for an era when China was opening to the world and the future seemed more prosperous and hopeful.', 'https://static01.nyt.com/images/2026/08/13/multimedia/13Biz-Newworld-Zhu-01-tlcg/13Biz-Newworld-Zhu-01-tlcg-mediumSquareAt3X.jpg', '2026-08-13T15:19:57+00:00', '2026-08-13T22:52:28.482508'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (323990, 13681, 'South China Morning Post', 'en', 'Zhu Rongji’s legacy: how the late premier reshaped state firms, Pudong and China’s economy', 'https://www.scmp.com/economy/china-economy/article/3363935/zhu-rongjis-legacy-how-late-premier-reshaped-state-firms-pudong-and-chinas-economy', 'Turn-of-the-century images of Zhu Rongji alongside former US president Bill Clinton have largely accompanied coverage following the former Chinese premier’s death on Wednesday. The moment in April 1999 was more than a diplomatic milestone. It underpinned some of China’s most consequential reforms that defined Zhu’s tenure, from its drive to join the World Trade Organization to an overhaul of the state sector and opening its markets to the world. And in recent years, Zhu’s historic trip to...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/d5d255f5-9e2a-4e18-8967-b47e2756e97d_26e38eea.jpg?itok=bJVRfk4G&v=1786619723', '2026-08-13T13:00:10+00:00', '2026-08-13T22:55:10.840002'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (323994, 13681, 'South China Morning Post', 'en', 'Malaysia’s Anwar looks back on relationship ‘well beyond affairs of state’ with Zhu Rongji', 'https://www.scmp.com/news/china/diplomacy/article/3363926/malaysias-anwar-looks-back-relationship-well-beyond-affairs-state-zhu-rongji', 'Tributes have been flooding in for former Chinese premier Zhu Rongji, the reformist statesman who played a leading role in integrating China’s economy into the global system and charmed neighbouring countries with his candid diplomacy. In a deeply personal tribute posted on social media, Malaysian Prime Minister Anwar Ibrahim described Zhu, who died on Wednesday at the age of 97, as “a good friend”. The pair worked together to strengthen economic ties between the two countries, building a...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/f2af0970-41f7-4b0e-8114-9584d59bef6e_7e5d6997.jpg?itok=hn-AFUtv&v=1786618063', '2026-08-13T11:30:54+00:00', '2026-08-13T22:55:10.875150'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
