INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312427, 13688, 'Aaj Tak', 'hi', 'भारत में लॉन्च हुए Pixel 11, Pixel Watch 5 और Pixel Tag, इतनी है कीमत', 'https://www.aajtak.in/technology/tech-news/story/google-pixel-11-pixel-watch-5-pixel-tag-launched-made-by-google-2026-ttecr-dskc-2620982-2026-08-13', 'गूगल ने अपने एक बड़े इवेंट का आयोजन किया है, जिसका नाम मेड बाय गूगल है. इस इवेंट के तहत कंपनी ने Pixel 11 सीरीज के अंदर चार स्मार्टफोन को लॉन्च किया है, जिसमें एक फोल्ड स्मार्टफोन का भी नाम शामिल है. इसके अलावा Pixel Watch और Pixel Tag को लॉन्च किया है, जिसका सीधा मुकाबला ऐपल AirTag के साथ होगा. आइए इसके बारे में डिटेल्स में जानते हैं.', '', '2026-08-13T01:22:35+00:00', '2026-08-13T02:01:18.604811'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
